data.value:
{
  // マッチが見つかったときに再生するパターン。組み込みは次の 3 つ:
  //   "match-found"  赤と白が 300 ms ごとに入れ替わる
  //   "pulse"        金色でゆっくり明滅する
  //   "steady"       金色で点灯する
  // 下で自分で定義したパターンの名前も指定できます。
  "pattern": "match-found",

  // 自分のパターン。color は #RRGGBB（#000000 は消灯）、brightness は 0-100、
  // durationMs は各ステップを表示する時間（ミリ秒）。effect は "solid"（既定）か "breathing"。
  "patterns": {
    // "blue-blink": {
    //   "steps": [
    //     { "color": "#0080FF", "durationMs": 250 },
    //     { "color": "#000000", "durationMs": 250 }
    //   ]
    // }
  },

  // キーボードごとの設定。"pattern" で上のパターンを上書き、"enabled": false でそのキーボードは光らせない。
  // id はトレイメニューの「キーボード」に表示されます。
  // "devices": { "keychron-q1-he-8k": { "pattern": "pulse" } },

  // 安全のための停止時間（秒）。クライアントが Accept 画面から進まない場合に備えます。
  "maxAlertSeconds": 30,

  // メニューの言語: "auto" は Windows に合わせる。"en" / "ja" で固定。次回起動時に反映されます。
  "language": "auto"
}
